1	package darksafe
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"math"
10		"sort"
11		"strings"
12	)
13	
14	// Reason constants for clusters that cannot enter a release plan.
15	const (
16		ReasonDisabled          = "集群已停用"
17		ReasonExcludeMatched    = "命中排除条件"
18		ReasonIncludeNotMatched = "未命中包含条件"
19	)
20	
21	// LabelCondition is a set of exact key-value matches; all must match.
22	type LabelCondition map[string]string
23	
24	// Cluster is a candidate target for a release.
25	type Cluster struct {
26		ID       string
27		Disabled bool
28		Tags     map[string]string
29	}
30	
31	// ReleasePlanInput describes an application release to plan offline.
32	type ReleasePlanInput struct {
33		App       string
34		Revision  string
35		Image     string
36		BatchSize int
37		// FirstBatchSize, when positive, caps batch 1 at this many clusters
38		// instead of BatchSize; later batches keep the BatchSize cap. Zero means
39		// unset (batch 1 uses BatchSize like every other batch). It must never
40		// exceed BatchSize.
41		FirstBatchSize int
42		Clusters       []Cluster
43		Include        []LabelCondition
44		Exclude        []LabelCondition
45		// SpreadBy, when non-empty, names a cluster tag whose value identifies a
46		// fault domain; each batch then contains at most one cluster per domain.
47		SpreadBy string
48	}
49	
50	// AppInfo identifies the application being released.
51	type AppInfo struct {
52		Name     string `json:"name"`
53		Revision string `json:"revision"`
54		Image    string `json:"image"`
55	}
56	
57	// Batch is a sequentially numbered group of cluster IDs.
58	type Batch struct {
59		Index    int      `json:"index"`
60		Clusters []string `json:"clusters"`
61	}
62	
63	// ExcludedCluster explains why a cluster is not in the plan.
64	type ExcludedCluster struct {
65		ID     string `json:"id"`
66		Reason string `json:"reason"`
67	}
68	
69	// ReleasePlan is the deterministic offline release plan.
70	type ReleasePlan struct {
71		App      AppInfo           `json:"app"`
72		Batches  []Batch           `json:"batches"`
73		Excluded []ExcludedCluster `json:"excluded"`
74	}
75	
76	// ParseReleaseInput reads a release plan document and validates its fields.
77	// Every string in the document — member names and values, in known fields
78	// and in unknown extra fields — must be legal text: invalid UTF-8 bytes and
79	// \uXXXX escapes naming an unpaired surrogate are rejected first, before any
80	// decoded string can be silently rewritten to "�" and compared. Every JSON
81	// object in the document — including unknown fields and their nested
82	// objects — must then have distinct member names; a name appearing twice
83	// (even with the same value, or via equivalent Unicode escapes) is rejected
84	// before any business validation runs. The document's structural nesting
85	// is capped at maxJSONNestingDepth levels in every field, known or not; a
86	// document that opens a 10001st level is rejected with
87	// errJSONDepthExceeded before any business validation or planning runs.
88	func ParseReleaseInput(data []byte) (ReleasePlanInput, error) {
89		if err := checkStrictText(data); err != nil {
90			return ReleasePlanInput{}, err
91		}
92		if err := checkDuplicateMembers(data); err != nil {
93			return ReleasePlanInput{}, err
94		}
95		dec := json.NewDecoder(bytes.NewReader(data))
96		dec.UseNumber()
97		var doc map[string]any
98		if err := dec.Decode(&doc); err != nil {
99			if isJSONDepthError(err) {
100				return ReleasePlanInput{}, errJSONDepthExceeded
101			}
102			return ReleasePlanInput{}, fmt.Errorf("JSON 格式错误: %w", err)
103		}
104		if dec.More() {
105			return ReleasePlanInput{}, errors.New("JSON 格式错误: 文档包含多余内容")
106		}
107		return buildReleaseInput(doc)
108	}
109	
110	// duplicateMemberError reports a JSON object whose member name appears more
111	// than once. Path is a JSONPath-style location that points at the object
112	// owning the duplicate (the duplicate member name itself is reported
113	// separately in field): "$" for the document root, "$.clusters[1]" for a
114	// cluster, "$.clusters[0].tags" for a tag object,
115	// "$.include[2]" / "$.exclude[1]" for a condition, and "$.foo.bar[0]" for
116	// objects nested inside unknown fields. A member name that is not a plain
117	// identifier is wrapped in brackets around a JSON string, so that characters
118	// in the name can never be read as hierarchy or an array index: a top-level
119	// member "meta.info" is at $["meta.info"] (distinct from the nested object
120	// $.meta.info), "zone[0]" stays one whole name at $["zone[0]"], and names
121	// that are empty or contain quotes, backslashes or control characters are
122	// rendered as decodable JSON strings such as $[""] or $["a\nb"]. DEL
123	// (U+007F) and the C1 controls (U+0080–U+009F) are \uXXXX escapes inside the
124	// JSON string rather than raw control characters, so the location stays
125	// readable and decodable; field names the duplicated member with the same
126	// JSON-string spelling.
127	type duplicateMemberError struct {
128		field string
129		path  string
130	}
131	
132	func (e *duplicateMemberError) Error() string {
133		return fmt.Sprintf("JSON 对象存在重复成员: 字段 %s 重复出现于 %s",
134			jsonEncodePathString(e.field), e.path)
135	}
136	
137	// checkDuplicateMembers walks every JSON object in data and rejects objects
138	// with duplicate member names. Names are compared after JSON decoding, so
139	// "env" and "env" are the same name while "env" and "ENV", or
140	// " env" and "env", are different. The first duplicate encountered in file
141	// order is reported: the walk is depth-first in document order, so the
142	// second occurrence that appears earliest wins, regardless of value type.
143	//
144	// The check is a policy over the shared structural walk (jsonwalk.go): the
145	// walker recognizes the nesting, decodes the member names and tracks each
146	// object's location; this check only keeps the seen-name set of each object.
147	// A document the walk cannot fully vouch for — an unrecognized structure,
148	// trailing content, or a malformed number the walk stopped on — is handed to
149	// the encoding/json walk, which reports the established format error (and
150	// any duplicate preceding the malformation) with the existing wording.
151	func checkDuplicateMembers(data []byte) error {
152		dup, recognized := scanDuplicateMembers(data)
153		// The nesting limit is a verdict by itself: it holds whether or not the
154		// document is otherwise well-formed and needs no json.Valid confirmation,
155		// so a too-deep document stops here instead of being scanned twice.
156		if errors.Is(dup, errJSONDepthExceeded) {
157			return dup
158		}
159		// json.Valid confirms the whole document — including every number the
160		// walk grammar-checked and any trailing content — is one well-formed
161		// JSON value, so a completed walk's verdict can be trusted directly.
162		// Legal numbers beyond float64 range (e.g. 1e400) are valid JSON and
163		// pass; whether a number is acceptable for a given field is decided
164		// later by business validation.
165		if recognized && json.Valid(data) {
166			return dup
167		}
168		return checkJSONFormatAndDuplicates(data)
169	}
170	
171	// scanDuplicateMembers runs the duplicate-member policy over the shared
172	// structural walk. It reports the first duplicate in file order — the walk
173	// is depth-first in document order, so the second occurrence that appears
174	// earliest wins — and whether the walk recognized the document's structure
175	// (no errUndecided and no text problem, both of which leave the verdict to
176	// the decoder walk). recognized does not by itself mean the document is
177	// well-formed JSON: the caller confirms that with json.Valid.
178	func scanDuplicateMembers(data []byte) (dup error, recognized bool) {
179		// Each entered object's frame id is unique, so the seen-name sets are
180		// keyed by the owning object's id; the walk needs no enter/exit events
181		// for them.
182		seen := make(map[uint64]map[string]struct{})
183		var w *jsonWalker
184		w = &jsonWalker{data: data, onMember: func(ownerID uint64, name string) error {
185			set := seen[ownerID]
186			if set == nil {
187				set = make(map[string]struct{})
188				seen[ownerID] = set
189			}
190			if _, ok := set[name]; ok {
191				dup = &duplicateMemberError{field: name, path: w.framePathByID(ownerID)}
192				return dup
193			}
194			set[name] = struct{}{}
195			return nil
196		}}
197		if err := w.walk(); err != nil && dup == nil {
198			if errors.Is(err, errJSONDepthExceeded) {
199				return err, true
200			}
201			return nil, false
202		}
203		return dup, true
204	}
205	
206	// checkJSONFormatAndDuplicates is the encoding/json walk that documents the
207	// raw structural walk cannot recognize are handed to. It reports the JSON
208	// format error with the established wording — and a duplicate member when
209	// its second occurrence precedes the malformation — exactly as the duplicate
210	// check always has for such documents. The Token API enforces no nesting
211	// limit of its own, so the walk carries the same maxJSONNestingDepth
212	// counter: a malformed document that is also too deep (e.g. one with no
213	// closing brackets at all) is refused with errJSONDepthExceeded instead of
214	// recursing down the reader's call stack and reporting "unclosed" later.
215	func checkJSONFormatAndDuplicates(data []byte) error {
216		dec := json.NewDecoder(bytes.NewReader(data))
217		// Numbers are only walked past, never interpreted: UseNumber keeps legal
218		// JSON numbers beyond float64 range (e.g. 1e400) from being turned into an
219		// unmarshal-overflow error here. Whether a number is acceptable for a given
220		// field is decided later by business validation.
221		dec.UseNumber()
222		depth := 0
223		if err := walkJSONValue(dec, "$", &depth); err != nil {
224			return err
225		}
226		if _, err := dec.Token(); err != io.EOF {
227			if err == nil {
228				return errors.New("JSON 格式错误: 文档包含多余内容")
229			}
230			if isJSONDepthError(err) {
231				return errJSONDepthExceeded
232			}
233			return fmt.Errorf("JSON 格式错误: %w", err)
234		}
235		return nil
236	}
237	
238	// enterContainer enforces the shared nesting limit on the Token walk: the
239	// root container is level 1 and each entered object or array adds one,
240	// exactly as in the raw walker. It returns errJSONDepthExceeded at the
241	// 10001st level.
242	func enterContainer(depth *int) error {
243		*depth++
244		if *depth > maxJSONNestingDepth {
245			return errJSONDepthExceeded
246		}
247		return nil
248	}
249	
250	// leaveContainer marks one container closed.
251	func leaveContainer(depth *int) {
252		*depth--
253	}
254	
255	// walkJSONValue reads one complete JSON value whose first token has not been
256	// consumed yet. Together with walkJSONObject and walkJSONArray it is the
257	// decoding half of checkJSONFormatAndDuplicates: it only runs for documents
258	// the shared structural walk could not recognize, to report the format error
259	// (or an earlier duplicate) with the established wording.
260	func walkJSONValue(dec *json.Decoder, path string, depth *int) error {
261		tok, err := dec.Token()
262		if err != nil {
263			if err == io.EOF {
264				return errors.New("JSON 格式错误: 文档为空")
265			}
266			if isJSONDepthError(err) {
267				return errJSONDepthExceeded
268			}
269			return fmt.Errorf("JSON 格式错误: %w", err)
270		}
271		return walkJSONValueToken(dec, path, tok, depth)
272	}
273	
274	// walkJSONValueToken reads the remainder of a value given its first token.
275	func walkJSONValueToken(dec *json.Decoder, path string, tok json.Token, depth *int) error {
276		if d, ok := tok.(json.Delim); ok {
277			if err := enterContainer(depth); err != nil {
278				return err
279			}
280			switch d {
281			case '{':
282				return walkJSONObject(dec, path, depth)
283			case '[':
284				return walkJSONArray(dec, path, depth)
285			default:
286				return fmt.Errorf("JSON 格式错误: 意外的分隔符 %q", d)
287			}
288		}
289		return nil // scalar value (string, number, bool, null)
290	}
291	
292	func walkJSONObject(dec *json.Decoder, path string, depth *int) error {
293		defer leaveContainer(depth)
294		seen := make(map[string]struct{})
295		for {
296			tok, err := dec.Token()
297			if err != nil {
298				if err == io.EOF {
299					return errors.New("JSON 格式错误: 对象未闭合")
300				}
301				if isJSONDepthError(err) {
302					return errJSONDepthExceeded
303				}
304				return fmt.Errorf("JSON 格式错误: %w", err)
305			}
306			if d, ok := tok.(json.Delim); ok {
307				if d == '}' {
308					return nil
309				}
310				return fmt.Errorf("JSON 格式错误: 意外的分隔符 %q", d)
311			}
312			key, ok := tok.(string)
313			if !ok {
314				return errors.New("JSON 格式错误: 对象成员名必须是字符串")
315			}
316			if _, dup := seen[key]; dup {
317				return &duplicateMemberError{field: key, path: path}
318			}
319			seen[key] = struct{}{}
320			vtok, err := dec.Token()
321			if err != nil {
322				if err == io.EOF {
323					return errors.New("JSON 格式错误: 缺少成员值")
324				}
325				if isJSONDepthError(err) {
326					return errJSONDepthExceeded
327				}
328				return fmt.Errorf("JSON 格式错误: %w", err)
329			}
330			if err := walkJSONValueToken(dec, joinMemberPath(path, key), vtok, depth); err != nil {
331				return err
332			}
333		}
334	}
335	
336	func walkJSONArray(dec *json.Decoder, path string, depth *int) error {
337		defer leaveContainer(depth)
338		for i := 0; ; i++ {
339			tok, err := dec.Token()
340			if err != nil {
341				if err == io.EOF {
342					return errors.New("JSON 格式错误: 数组未闭合")
343				}
344				if isJSONDepthError(err) {
345					return errJSONDepthExceeded
346				}
347				return fmt.Errorf("JSON 格式错误: %w", err)
348			}
349			if d, ok := tok.(json.Delim); ok && d == ']' {
350				return nil
351			}
352			if err := walkJSONValueToken(dec, joinIndexPath(path, i), tok, depth); err != nil {
353				return err
354			}
355		}
356	}
357	
358	// isJSONDepthError reports whether err is encoding/json's own
359	// nesting-limit failure (Decode/Valid enforce it even though the Token
360	// API does not). The message is matched rather than a typed error,
361	// because the scanner's "exceeded max depth" SyntaxError is not exported
362	// as one.
363	func isJSONDepthError(err error) bool {
364		return err != nil && strings.Contains(err.Error(), "exceeded max depth")
365	}
366	
367	func buildReleaseInput(doc map[string]any) (ReleasePlanInput, error) {
368		app, err := requiredString(doc, "app")
369		if err != nil {
370			return ReleasePlanInput{}, err
371		}
372		revision, err := requiredString(doc, "revision")
373		if err != nil {
374			return ReleasePlanInput{}, err
375		}
376		image, err := requiredString(doc, "image")
377		if err != nil {
378			return ReleasePlanInput{}, err
379		}
380		batchSize, err := positiveInt(doc, "batchSize")
381		if err != nil {
382			return ReleasePlanInput{}, err
383		}
384		firstBatchSize, err := optionalPositiveInt(doc, "firstBatchSize")
385		if err != nil {
386			return ReleasePlanInput{}, err
387		}
388		if err := checkFirstBatchSize(firstBatchSize, batchSize); err != nil {
389			return ReleasePlanInput{}, err
390		}
391		spreadBy, err := optionalSpreadBy(doc)
392		if err != nil {
393			return ReleasePlanInput{}, err
394		}
395		clusters, err := parseClusters(doc["clusters"])
396		if err != nil {
397			return ReleasePlanInput{}, err
398		}
399		include, err := parseConditions(doc, "include")
400		if err != nil {
401			return ReleasePlanInput{}, err
402		}
403		exclude, err := parseConditions(doc, "exclude")
404		if err != nil {
405			return ReleasePlanInput{}, err
406		}
407	
408		return ReleasePlanInput{
409			App:            app,
410			Revision:       revision,
411			Image:          image,
412			BatchSize:      batchSize,
413			FirstBatchSize: firstBatchSize,
414			Clusters:       clusters,
415			Include:        include,
416			Exclude:        exclude,
417			SpreadBy:       spreadBy,
418		}, nil
419	}
420	
421	// optionalSpreadBy reads the optional "spreadBy" field: absent or an empty
422	// string disables fault-domain spreading; a non-string value or a string of
423	// only whitespace is rejected. The tag key is used exactly as written.
424	func optionalSpreadBy(doc map[string]any) (string, error) {
425		v, ok := doc["spreadBy"]
426		if !ok {
427			return "", nil
428		}
429		s, ok := v.(string)
430		if !ok {
431			return "", fmt.Errorf("字段 %q 必须是字符串", "spreadBy")
432		}
433		if err := checkSpreadBy(s); err != nil {
434			return "", err
435		}
436		return s, nil
437	}
438	
439	// checkSpreadBy rejects a spreadBy value that is neither empty nor a usable
440	// tag key: a string of only whitespace can never match a valid tag key.
441	func checkSpreadBy(s string) error {
442		if s != "" && strings.TrimSpace(s) == "" {
443			return fmt.Errorf("字段 %q 不能只含空白", "spreadBy")
444		}
445		return nil
446	}
447	
448	// checkFirstBatchSize applies the firstBatchSize rule shared by the JSON
449	// entry and a directly constructed Go config: zero means "not set" and is
450	// always legal; a set value must be a positive integer no larger than
451	// batchSize. The value is never rounded, truncated or clamped into range —
452	// an illegal one is a configuration error.
453	func checkFirstBatchSize(firstBatchSize, batchSize int) error {
454		if firstBatchSize < 0 {
455			return errors.New(`字段 "firstBatchSize" 必须是正整数`)
456		}
457		if firstBatchSize > batchSize {
458			return errors.New(`字段 "firstBatchSize" 不能大于 "batchSize"`)
459		}
460		return nil
461	}
462	
463	// ValidateReleaseInput checks that a release configuration is well-formed.
464	// Every string is first required to be legal UTF-8 — app, revision, image,
465	// spreadBy, every candidate's ID and tag keys/values (disabled and
466	// filtered-out candidates included), and every include/exclude condition's
467	// keys and values — because invalid bytes would later be rewritten to "�"
468	// while the plan is written as JSON and could merge two distinct identities
469	// or take part in label matching as an ordinary value. That text check runs
470	// before any business rule, in a fixed order (field order, then candidate
471	// and condition positions from zero, then keys in ascending order), so the
472	// one problem it reports never depends on map iteration. Business
473	// validation then runs as before: app/revision/image are non-empty,
474	// batchSize is a positive integer, firstBatchSize is zero (unset) or a
475	// positive integer no larger than batchSize, spreadBy is empty or a usable
476	// tag key
477	// (not whitespace-only), cluster IDs are unique across every candidate
478	// (including disabled and filtered-out clusters), and tag/condition keys
479	// are non-empty. Errors name the field and the position in its list; within
480	// a cluster the ID is checked before its tags, and tag keys are examined in
481	// ascending order so repeated calls report the same error. The input is
482	// never mutated. MakeReleasePlan calls this automatically; library callers
483	// may use it to validate without planning.
484	func ValidateReleaseInput(in ReleasePlanInput) error {
485		if err := validateStrictText(in); err != nil {
486			return err
487		}
488		if strings.TrimSpace(in.App) == "" {
489			return errors.New(`字段 "app" 不能为空或只含空白`)
490		}
491		if strings.TrimSpace(in.Revision) == "" {
492			return errors.New(`字段 "revision" 不能为空或只含空白`)
493		}
494		if strings.TrimSpace(in.Image) == "" {
495			return errors.New(`字段 "image" 不能为空或只含空白`)
496		}
497		if in.BatchSize <= 0 {
498			return errors.New(`字段 "batchSize" 必须是正整数`)
499		}
500		if err := checkFirstBatchSize(in.FirstBatchSize, in.BatchSize); err != nil {
501			return err
502		}
503		if err := checkSpreadBy(in.SpreadBy); err != nil {
504			return err
505		}
506		ids := newClusterIDSet(len(in.Clusters))
507		for i, c := range in.Clusters {
508			if err := ids.check(i, c.ID); err != nil {
509				return err
510			}
511			if err := validateTagKeys(i, c.Tags); err != nil {
512				return err
513			}
514		}
515		if err := validateConditionKeys("include", in.Include); err != nil {
516			return err
517		}
518		if err := validateConditionKeys("exclude", in.Exclude); err != nil {
519			return err
520		}
521		return nil
522	}
523	
524	// validateTagKeys applies the shared label-key rule to one cluster's tags,
525	// reporting the cluster's position in the candidate list.
526	func validateTagKeys(clusterIndex int, tags map[string]string) error {
527		if hasEmptyLabelKey(tags) {
528			return fmt.Errorf("clusters[%d] 的标签键不能为空", clusterIndex)
529		}
530		return nil
531	}
532	
533	// validateConditionKeys applies the shared condition rules to every condition
534	// in original order, so the first invalid condition is reported.
535	func validateConditionKeys(field string, conds []LabelCondition) error {
536		for i, cond := range conds {
537			if err := validateCondition(field, i, cond); err != nil {
538				return err
539			}
540		}
541		return nil
542	}
543	
544	func requiredString(doc map[string]any, field string) (string, error) {
545		v, ok := doc[field]
546		if !ok {
547			return "", fmt.Errorf("缺少必需字段 %q", field)
548		}
549		s, ok := v.(string)
550		if !ok {
551			return "", fmt.Errorf("字段 %q 必须是字符串", field)
552		}
553		if strings.TrimSpace(s) == "" {
554			return "", fmt.Errorf("字段 %q 不能为空或只含空白", field)
555		}
556		return s, nil
557	}
558	
559	// positiveInt reads a required field as a positive integer. The literal must
560	// be an integral JSON number whose value is representable in full by the Go
561	// int of the running environment: a value beyond math.MaxInt is rejected here
562	// rather than narrowed by an int() conversion, which on a 32-bit environment
563	// could turn 4294967297 into 1 (or a larger value into zero or a negative
564	// number). No truncation, rounding, default substitution or clamping to the
565	// maximum ever happens — such a value is a configuration error regardless of
566	// what int it would collapse into.
567	func positiveInt(doc map[string]any, field string) (int, error) {
568		v, ok := doc[field]
569		if !ok {
570			return 0, fmt.Errorf("缺少必需字段 %q", field)
571		}
572		return positiveIntValue(v, field)
573	}
574	
575	// optionalPositiveInt reads an optional field with exactly the positiveInt
576	// rule; an absent field yields 0 ("not set"). A field that is present must
577	// hold a legal positive integer literal — an explicit zero, a negative
578	// number, a fraction, a non-number or an out-of-range value is rejected, never
579	// ignored or narrowed.
580	func optionalPositiveInt(doc map[string]any, field string) (int, error) {
581		v, ok := doc[field]
582		if !ok {
583			return 0, nil
584		}
585		return positiveIntValue(v, field)
586	}
587	
588	// positiveIntValue validates one decoded JSON value as a positive integer
589	// literal for field, shared by the required and optional field readers.
590	func positiveIntValue(v any, field string) (int, error) {
591		n, ok := v.(json.Number)
592		if !ok {
593			return 0, fmt.Errorf("字段 %q 必须是正整数", field)
594		}
595		i, err := n.Int64()
596		if err != nil || i <= 0 || i > math.MaxInt {
597			return 0, fmt.Errorf("字段 %q 必须是正整数", field)
598		}
599		return int(i), nil
600	}
601	
602	func parseClusters(v any) ([]Cluster, error) {
603		if v == nil {
604			return nil, errors.New("缺少必需字段 \"clusters\"")
605		}
606		raw, ok := v.([]any)
607		if !ok {
608			return nil, errors.New("字段 \"clusters\" 必须是数组")
609		}
610		clusters := make([]Cluster, 0, len(raw))
611		ids := newClusterIDSet(len(raw))
612		for i, item := range raw {
613			obj, ok := item.(map[string]any)
614			if !ok {
615				return nil, fmt.Errorf("clusters[%d] 必须是对象", i)
616			}
617			id, err := clusterIDFromJSON(obj, i, ids)
618			if err != nil {
619				return nil, err
620			}
621	
622			disabled := false
623			if dv, present := obj["disabled"]; present {
624				b, ok := dv.(bool)
625				if !ok {
626					return nil, fmt.Errorf("集群 %q 的 \"disabled\" 必须是布尔值", id)
627				}
628				disabled = b
629			}
630	
631			tags := map[string]string{}
632			if tv, present := obj["tags"]; present {
633				tm, ok := tv.(map[string]any)
634				if !ok {
635					return nil, fmt.Errorf("集群 %q 的 \"tags\" 必须是对象", id)
636				}
637				tags, err = labelsFromJSON(tm,
638					func(string) error { return fmt.Errorf("集群 %q 的标签键不能为空", id) },
639					func(k string) error { return fmt.Errorf("集群 %q 的标签 %q 值必须是字符串", id, k) },
640				)
641				if err != nil {
642					return nil, err
643				}
644			}
645	
646			clusters = append(clusters, Cluster{ID: id, Disabled: disabled, Tags: tags})
647		}
648		return clusters, nil
649	}
650	
651	// clusterIDFromJSON reads the "id" member of one candidate object and applies
652	// the shared cluster-identity rule. A missing member or a non-string value is
653	// a JSON decoding problem with its own reason; an empty or duplicate ID is
654	// reported by the shared rule exactly as for a directly constructed config.
655	func clusterIDFromJSON(obj map[string]any, index int, ids *clusterIDSet) (string, error) {
656		v, ok := obj["id"]
657		if !ok {
658			return "", fmt.Errorf("clusters[%d]: 缺少必需字段 %q", index, "id")
659		}
660		id, ok := v.(string)
661		if !ok {
662			return "", fmt.Errorf("clusters[%d]: 字段 %q 必须是字符串", index, "id")
663		}
664		if err := ids.check(index, id); err != nil {
665			return "", err
666		}
667		return id, nil
668	}
669	
670	// parseConditions reads the optional include/exclude field from the decoded
671	// document. An absent field means "no conditions" (the same as an explicit
672	// empty array); a field that is present must be an array of condition
673	// objects. An explicit JSON null is a field type error — it must not be read
674	// as "no conditions", which would silently drop the filter the author wrote.
675	func parseConditions(doc map[string]any, field string) ([]LabelCondition, error) {
676		v, ok := doc[field]
677		if !ok {
678			return []LabelCondition{}, nil
679		}
680		raw, ok := v.([]any)
681		if !ok {
682			return nil, fmt.Errorf("字段 %q 必须是条件数组", field)
683		}
684		conds := make([]LabelCondition, 0, len(raw))
685		for i, item := range raw {
686			obj, ok := item.(map[string]any)
687			if !ok {
688				return nil, fmt.Errorf("%s[%d] 必须是对象", field, i)
689			}
690			cond, err := labelsFromJSON(obj,
691				func(string) error { return fmt.Errorf("%s[%d] 的标签键不能为空", field, i) },
692				func(k string) error { return fmt.Errorf("%s[%d] 的标签 %q 值必须是字符串", field, i, k) },
693			)
694			if err != nil {
695				return nil, err
696			}
697			if err := validateCondition(field, i, cond); err != nil {
698				return nil, err
699			}
700			conds = append(conds, cond)
701		}
702		return conds, nil
703	}
704	
705	// MakeReleasePlan selects available clusters, orders them by ID, and splits
706	// them into batches. When SpreadBy names a tag, each batch holds at most one
707	// cluster per value of that tag (its fault domain) and every selected cluster
708	// must carry the tag. When FirstBatchSize is set, batch 1 is capped at that
709	// many clusters and every later batch at BatchSize; the first-batch cap is
710	// only a cap — a batch may close short when clusters run out or fault domains
711	// conflict, and no empty batch is ever emitted. It validates the input first
712	// and never mutates it.
713	//
714	// When every candidate is filtered out, the returned error lists each
715	// candidate's rejection reason on its own line, ascending by the original
716	// ID. An ID containing a double quote, backslash, control character or
717	// U+2028/U+2029 is displayed as a quoted JSON string with those characters
718	// escaped (see rejectreport.go), so one candidate always occupies exactly
719	// one line and the original ID can be recovered from the display; this is
720	// only a display spelling — the ID itself is never altered or re-compared.
721	func MakeReleasePlan(in ReleasePlanInput) (ReleasePlan, error) {
722		if err := ValidateReleaseInput(in); err != nil {
723			return ReleasePlan{}, err
724		}
725		if len(in.Clusters) == 0 {
726			return ReleasePlan{}, errors.New("没有可发布的集群：未提供候选集群")
727		}
728	
729		selected := []string{}
730		excluded := []ExcludedCluster{}
731		for _, c := range in.Clusters {
732			switch {
733			case c.Disabled:
734				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonDisabled})
735			case matchesAny(c.Tags, in.Exclude):
736				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonExcludeMatched})
737			case len(in.Include) > 0 && !matchesAny(c.Tags, in.Include):
738				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonIncludeNotMatched})
739			default:
740				selected = append(selected, c.ID)
741			}
742		}
743	
744		sort.Strings(selected)
745		sort.Slice(excluded, func(i, j int) bool { return excluded[i].ID < excluded[j].ID })
746	
747		if len(selected) == 0 {
748			var b strings.Builder
749			b.WriteString("没有符合规则的可用集群，各候选集群未入选原因：")
750			for _, e := range excluded {
751				b.WriteString("\n  ")
752				b.WriteString(reportClusterID(e.ID))
753				b.WriteString("：")
754				b.WriteString(e.Reason)
755			}
756			return ReleasePlan{}, errors.New(b.String())
757		}
758	
759		var batches []Batch
760		firstCap := in.BatchSize
761		if in.FirstBatchSize > 0 {
762			firstCap = in.FirstBatchSize
763		}
764		if in.SpreadBy == "" {
765			batches = chunkBatches(selected, in.BatchSize, firstCap)
766		} else {
767			domains, err := faultDomains(in.Clusters, selected, in.SpreadBy)
768			if err != nil {
769				return ReleasePlan{}, err
770			}
771			batches = spreadBatches(selected, domains, in.BatchSize, firstCap)
772		}
773	
774		return ReleasePlan{
775			App:      AppInfo{Name: in.App, Revision: in.Revision, Image: in.Image},
776			Batches:  batches,
777			Excluded: excluded,
778		}, nil
779	}
780	
781	// chunkBatches splits the ascending IDs into batches of at most batchSize,
782	// except batch 1 which is capped at firstBatchSize instead (callers pass
783	// batchSize when no separate first-batch cap is set). Each batch's Clusters
784	// gets its own backing array: a subslice of selected would leave spare
785	// capacity pointing at the next batch's IDs, so a caller appending to one
786	// batch's list would overwrite the following batch.
787	//
788	// The batch length is derived from the count that remains (the smaller of the
789	// capacity and the remainder), never by adding the offset to the capacity:
790	// the capacity is only an upper bound and may be a huge legal value such as
791	// math.MaxInt, and i + capacity would then wrap into a negative slice length
792	// after a small first batch.
793	func chunkBatches(selected []string, batchSize, firstBatchSize int) []Batch {
794		batches := []Batch{}
795		for i := 0; i < len(selected); {
796			capacity := batchSize
797			if len(batches) == 0 {
798				capacity = firstBatchSize
799			}
800			size := len(selected) - i
801			if capacity < size {
802				size = capacity
803			}
804			end := i + size
805			clusters := make([]string, size)
806			copy(clusters, selected[i:end])
807			batches = append(batches, Batch{Index: len(batches) + 1, Clusters: clusters})
808			i = end
809		}
810		return batches
811	}
812	
813	// faultDomains maps every selected cluster ID to the exact value of its
814	// spreadBy tag. A selected cluster missing the tag fails the whole plan;
815	// selected is ascending, so the smallest such ID is reported. An empty
816	// string tag value is a valid fault domain, distinct from a missing tag.
817	func faultDomains(clusters []Cluster, selected []string, spreadBy string) (map[string]string, error) {
818		tagsByID := make(map[string]map[string]string, len(clusters))
819		for _, c := range clusters {
820			tagsByID[c.ID] = c.Tags
821		}
822		domains := make(map[string]string, len(selected))
823		for _, id := range selected {
824			v, ok := tagsByID[id][spreadBy]
825			if !ok {
826				return nil, fmt.Errorf("集群 %q 缺少故障域标签 %q", id, spreadBy)
827			}
828			domains[id] = v
829		}
830		return domains, nil
831	}
832	
833	// spreadBatches packs the ascending IDs into batches of at most batchSize
834	// with at most one cluster per fault domain in each batch — except batch 1,
835	// whose capacity is firstBatchSize (callers pass batchSize when no separate
836	// first-batch cap is set). Each batch takes the smallest still-unscheduled
837	// IDs whose domains do not conflict with the batch; conflicting clusters are
838	// deferred to later batches, so a batch may be short only when no
839	// non-conflicting cluster remains. Every ID appears in exactly one batch and
840	// IDs stay ascending within a batch.
841	func spreadBatches(selected []string, domains map[string]string, batchSize, firstBatchSize int) []Batch {
842		remaining := append([]string(nil), selected...)
843		batches := []Batch{}
844		for len(remaining) > 0 {
845			capacity := batchSize
846			if len(batches) == 0 {
847				capacity = firstBatchSize
848			}
849			// The map never holds more entries than there are remaining clusters,
850			// so size it by them — never by the capacity, which is only an upper
851			// bound and may be a huge legal value (e.g. 1e9 meaning "no limit").
852			used := make(map[string]struct{}, min(capacity, len(remaining)))
853			batch := []string{}
854			deferred := []string{}
855			for _, id := range remaining {
856				d := domains[id]
857				if _, conflict := used[d]; len(batch) < capacity && !conflict {
858					used[d] = struct{}{}
859					batch = append(batch, id)
860				} else {
861					deferred = append(deferred, id)
862				}
863			}
864			batches = append(batches, Batch{Index: len(batches) + 1, Clusters: batch})
865			remaining = deferred
866		}
867		return batches
868	}
869	
870	func matchesAny(tags map[string]string, conditions []LabelCondition) bool {
871		for _, cond := range conditions {
872			if matchesAll(tags, cond) {
873				return true
874			}
875		}
876		return false
877	}
878	
879	func matchesAll(tags map[string]string, cond LabelCondition) bool {
880		for k, v := range cond {
881			tv, ok := tags[k]
882			if !ok || tv != v {
883				return false
884			}
885		}
886		return true
887	}
